def scheduler(raw):
 win=raw['phases']['measurement']['window'];ss=[v for v in raw['telemetry']['samples'] if win['start_time_ns']<=v['time_ns']<win['end_time_ns']];rows=[]
 for i,meta in raw['worker_identities'].items():
  pid=meta['pid'];vals=[(v['time_ns'],q) for v in ss for q in v.get('scheduler_observation',[]) if q['pid']==pid]
  if len(vals)<2:rows.append({'worker':i,'status':'INSUFFICIENT_TELEMETRY'});continue
  a,b=vals[0][1],vals[-1][1];aa={r['tid']:r for r in a['thread_schedstat']};bb={r['tid']:r for r in b['thread_schedstat']};common=aa.keys()&bb.keys();elapsed=(vals[-1][0]-vals[0][0])/1e9
  rows.append({'worker':i,'elapsed_seconds':elapsed,'tracked_persistent_threads':len(common),'CPU_run_seconds':sum(max(0,bb[j]['cpu_run_ns']-aa[j]['cpu_run_ns']) for j in common)/1e9,'CPU_runnable_wait_seconds':sum(max(0,bb[j]['cpu_runqueue_wait_ns']-aa[j]['cpu_runqueue_wait_ns']) for j in common)/1e9,'voluntary_context_switch_delta':b['context_switches_voluntary']-a['context_switches_voluntary'],'involuntary_context_switch_delta':b['context_switches_involuntary']-a['context_switches_involuntary'],'notes':'Persistent thread schedstat deltas; GPU synchronization may spin on CPU. CPU run time is not CPU frontend time, and runnable wait does not include blocked off-CPU waits.'})
 return rows

